//! `tomedoom`: the Tome of Doom (the book): opening/closing, sucking monsters in, draining their life,
//! collecting wisps (orbs) to refill its power, the hero <-> book hookup, button mashing.
//! Port of `Game Logic Modules/Globals/Objects/Tome_Of_Doom/tomedoom__<sha8>/` (TomeDoom.c, Tod_Sucking.c,
//! wisp_tomeCollect.c). Reference build: tomedoom__802a33e5 (EP1L01); the 29 other builds differ in
//! per-level literals and a few code shapes, see [`builds`] (generated by tools/rustport/gen_builds.py).
//!
//! The module's globals are SHARED by every instance of the module (the engine only swaps
//! `pLocalDataTome` per instance), exactly as on the PS2; they live in the module data image.
#![allow(non_snake_case, non_upper_case_globals, unused_variables, unused_mut, unused_assignments)]
#![allow(clippy::all)]

pub mod builds;
mod tod_sucking;
mod tome_doom;
mod wisp_tome_collect;

pub use tod_sucking::*;
pub use tome_doom::*;
pub use wisp_tome_collect::*;

use crate::engine::{Engine, Ptr};
use crate::logic::ModuleDef;

pub static MODULE: ModuleDef = ModuleDef {
    name: "tomedoom",
    data_size: 0xe0,
    ctor: tomedoomConstructor,
    dtor: tomedoomDestructor,
    register: None,
    init: &[],
    build_init: None,
};

/// Index of a build in [`builds::BUILDS`] by the first 8 hex digits of its SHA-1.
pub fn build_index(sha8: &str) -> Option<usize> {
    builds::BUILDS.iter().position(|b| b.sha8 == sha8)
}

